  | 'SCROLL'
  | 'HOVER'
  | 'DOUBLE_CLICK'
  | 'RIGHT_CLICK'
  | 'LOCATE'
  | 'WAIT_FOR_VISUAL_STATE';

export interface AtomicAction {
  readonly stepId: string;
  readonly type: AtomicActionType;
  readonly semanticTarget: string;
  readonly valueRef?: string;
  readonly keyName?: string;
  readonly scroll?: {
    readonly scrollType:
      | 'singleAction'
      | 'scrollToBottom'
      | 'scrollToTop'
      | 'scrollToRight'
      | 'scrollToLeft';
    readonly direction?: 'down' | 'up' | 'left' | 'right';
    readonly distance?: number | null;
  };
  readonly timeoutMs: number;
  readonly riskLevel: 'LOW' | 'MEDIUM' | 'HIGH';
  readonly expectedEffect?: ExpectedActionEffect;
}
```

